/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_isurCd kisComCd repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (ipt_isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = "";
    str += "isurCd : " + ipt_isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('ipt_searchCorpName').setValue(comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", ipt_isurCd);
    $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "char");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            await scwin.fnSearchInit();
        }
    }
    /* sdd-asis-lifecycle:end */
};
